package parse

import (
 \"reflect\"
 \"regexp\"
 \"strings\"

 \"github.com/gravitational/trace\"
 \"github.com/gravitational/teleport/lib/utils\"
 \"github.com/vulcand/predicate\"
)

const ( LiteralNamespace=\"literal\"; EmailNamespace=\"email\"; EmailLocalFnName=\"local\"; RegexpNamespace=\"regexp\"; RegexpMatchFnName=\"match\"; RegexpNotMatchFnName=\"not_match\"; RegexpReplaceFnName=\"replace\" )

// Expression is a string expression with optional static surroundings.
type Expression struct { prefix,suffix string; expr Expr; namespace,variable string }
func (e *Expression) Namespace() string { return e.namespace }
func (e *Expression) Name() string { return e.variable }
func (e *Expression) Interpolate(traits map[string][]string, validation ...func(string,string)error)([]string,error) {
 var validate func(string,string)error; if len(validation)>0 {validate=validation[0]}
 if err:=validateVars(e.expr,validate); err"'!=nil{return nil,err}
 ctx:=EvaluateContext{VarValue:func(v VarExpr)([]string,error){ vals,ok:=traits[v.Name]; if !ok{return nil,trace.NotFound("variable %s is not found",v.String())}; return vals,nil }}
 vals,err:=stringValues(e.expr,ctx); if err!=nil{return nil,trace.Wrap(err)}
 out:=make([]string,0,len(vals)); for _,v:=range vals {if v!="" {out=append(out,e.prefix+v+e.suffix)}}
 if len(out)==0 {return nil,trace.NotFound("variable interpolation result is empty")}; return out,nil
}
func validateVars(e Expr, validate func(string,string)error) error { switch n:=e.(type) {case VarExpr: if n.Name=="" {return trace.BadParameter("incomplete variable %s",n.String())}; if validate!=nil {return validate(n.Namespace,n.Name)}; case EmailLocalExpr: return validateVars(n.Input,validate); case RegexpReplaceExpr: return validateVars(n.Input,validate)}; return nil }
func validateExpr(e Expr) error { return validateVars(e,nil) }
var reVariable=regexp.MustCompile(`''^([''^{}]*){{([''^{}]*)}}([''^{}]*)$`)
func splitTemplate(input string)(string,string,string,bool,error) { s:=strings.TrimSpace(input); m:=reVariable.FindStringSubmatch(s); if m!=nil {return m[1],strings.TrimSpace(m[2]),m[3],true,nil}; if strings.Contains(s,"{{") || strings.Contains(s,"}}") || strings.ContainsAny(s,"{}") {return "","","",false,trace.BadParameter("malformed template usage %q: expected {{expression}}",input)}; return "",s,"",false,nil }
func NewExpression(input string)(*Expression,error) { pre,body,suf,templ,err:=splitTemplate(input); if err!=nil{return nil,err}; if !templ {return &Expression{expr:StringLitExpr{body},namespace:LiteralNamespace,variable:body},nil}; node,err:=parse(body); if err!=nil{return nil,trace.BadParameter("invalid expression %q: %v",input,err)}; if node.Kind()!=reflect.String {return nil,trace.BadParameter("expression %q does not evaluate to a string",input)}; if err:=validateExpr(node); err!=nil{return nil,err}; e:=&Expression{prefix:pre,suffix:suf,expr:node}; if v,ok:=node.(VarExpr);ok {e.namespace,e.variable=v.Namespace,v.Name}; return e,nil }
func buildVarExpr(parts []string)(any,error) {if len(parts)==1 {switch parts[0] {case "internal","external","literal": return VarExpr{Namespace:parts[0]},nil}; return nil,trace.BadParameter("unsupported namespace %q; expected namespace.name",parts[0])}; if len(parts)!=2 || parts[1]=="" {return nil,trace.BadParameter("variable must have exactly two components: namespace.name")}; switch parts[0] {case "internal","external","literal": return VarExpr{Namespace:parts[0],Name:parts[1]},nil}; return nil,trace.BadParameter("unsupported namespace %q",parts[0]) }
func buildVarExprFromProperty(base,key any)(any,error) { v,ok:=base.(VarExpr); if !ok || v.Name!="" {return nil,trace.BadParameter("variable must have exactly two components: namespace.name")}; name,ok:=key.(string); if !ok || name=="" {return nil,trace.BadParameter("variable index must be a nonempty string name")}; return VarExpr{Namespace:v.Namespace,Name:name},nil }
func stringArg(arg any, fn string)(Expr,error) { var e Expr; switch v:=arg.(type) {case string:e=StringLitExpr{v}; case Expr:e=v; default:return nil,trace.BadParameter("%s requires a string argument",fn)}; if e.Kind()!=reflect.String{return nil,trace.BadParameter("%s requires a string argument",fn)}; return e,nil }
func constArg(arg any,fn string)(string,error) {v,ok:=arg.(string); if !ok {return "",trace.BadParameter("%s requires a constant string argument",fn)}; return v,nil}
func parse(src string)(Expr,error) {
 if len(src)>65536 {return nil,trace.BadParameter("expression exceeds maximum length")}
 p,_:=predicate.NewParser(predicate.Def{GetIdentifier:buildVarExpr,GetProperty:buildVarExprFromProperty,Functions:map[string]interface{}{
 "email.local":func(arg any)(Expr,error){e,err:=stringArg(arg,"email.local");if err!=nil{return nil,err};return EmailLocalExpr{Input:e},nil},
 "regexp.replace":func(source,pat,repl any)(Expr,error){e,err:=stringArg(source,"regexp.replace");if err!=nil{return nil,err}; p,err:=constArg(pat,"regexp.replace pattern");if err!=nil{return nil,err}; r,err:=constArg(repl,"regexp.replace replacement");if err!=nil{return nil,err}; re,err:=compileRegex(p);if err!=nil{return nil,err};return RegexpReplaceExpr{Input:e,Pattern:p,Replacement:r,re:re},nil},
 "regexp.match":func(arg any)(Expr,error){p,err:=constArg(arg,"regexp.match");if err!=nil{return nil,err};re,err:=compileRegex(p);if err!=nil{return nil,err};return RegexpMatchExpr{Pattern:p,re:re},nil},
 "regexp.not_match":func(arg any)(Expr,error){p,err:=constArg(arg,"regexp.not_match");if err!=nil{return nil,err};re,err:=compileRegex(p);if err!=nil{return nil,err};return RegexpNotMatchExpr{Pattern:p,re:re},nil},
 }})
 result,err:=p.Parse(src);if err!=nil{return nil,trace.BadParameter("invalid expression %q: %v",src,err)}; node,ok:=result.(Expr);if !ok{return nil,trace.BadParameter("expected variable or function expression, got %q",src)};return node,nil
}
type Matcher interface {Match(string)bool}
type MatcherFn func(string)bool
func (f MatcherFn) Match(s string)bool{return f(s)}
func NewAnyMatcher(inputs []string)(Matcher,error){ms:=make([]Matcher,0,len(inputs));for _,s:=range inputs{m,err:=NewMatcher(s);if err!=nil{return nil,err};ms=append(ms,m)};return MatcherFn(func(s string)bool{for _,m:=range ms{if m.Match(s){return true}};return false}),nil}
type MatchExpression struct { Prefix,Suffix string; Expr Expr }
func (m *MatchExpression) Match(in string)bool {if !strings.HasPrefix(in,m.Prefix)||!strings.HasSuffix(in,m.Suffix)||len(in)<len(m.Prefix)+len(m.Suffix){return false}; middle:=in[len(m.Prefix):len(in)-len(m.Suffix)]; v,err:=m.Expr.Evaluate(EvaluateContext{MatcherInput:middle});return err==nil && v==true}
func NewMatcher(input string)(Matcher,error){pre,body,suf,templ,err:=splitTemplate(input);if err!=nil{return nil,err};if !templ {pattern:=body;if !strings.HasPrefix(body,"''^")||!strings.HasSuffix(body,"$"){pattern="''^"+utils.GlobToRegexp(body)+"$"};re,err:=compileRegex(pattern);if err!=nil{return nil,err};return &MatchExpression{Expr:RegexpMatchExpr{Pattern:pattern,re:re}},nil}; node,err:=parse(body);if err!=nil{return nil,err};if node.Kind()!=reflect.Bool{return nil,trace.BadParameter("matcher %q does not evaluate to a boolean",input)};return &MatchExpression{Prefix:pre,Suffix:suf,Expr:node},nil}
EOF
